package wgmodern;
import java.util.*;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.level.biome.Biomes;import net.minecraftforge.gametest.*;import tc4revival.aspect.*;import thaumcraft.api.visnet.*;
@GameTestHolder("witchinggadgets") @PrefixGameTestTemplate(false)
public class TerraformServerTests {
 @GameTest(template="empty") public static void terraformerRequiresBothCostsAndChangesOnlyOneBiomeCell(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(3,3,3));l.setBlockAndUpdate(p,Content.TERRAFORMER.get().defaultBlockState());l.setBlockAndUpdate(p.above(),Terraformer.FOCI.get("desert").get().defaultBlockState());var t=(Terraformer.Tile)l.getBlockEntity(p);var a=TCAspects.catalog().require("ignis");var target=p.east(4);tc4revival.content.WorldBiomeChanges.changeColumn(l,target,Biomes.PLAINS);tc4revival.content.WorldBiomeChanges.changeColumn(l,target.east(4),Biomes.PLAINS);h.assertTrue(t.addToContainer(a,8)==0,"Focus accepts its original essentia");h.assertTrue(!t.transform(l,target,Biomes.DESERT,a)&&t.stored.amount(a)==8,"No relay energy means no biome edit or essentia cost");var source=new Source(l,p.west(2));VisNetHandler.register(source);try{h.assertTrue(t.transform(l,target,Biomes.DESERT,a),"Four terra centivis and four essentia transform one modern column");h.assertTrue(t.stored.amount(a)==4&&source.available==16,"Exactly four of both resources consumed");h.assertTrue(l.getBiomeManager().getNoiseBiomeAtPosition(target).is(Biomes.DESERT)&&l.getBiomeManager().getNoiseBiomeAtPosition(target.east(4)).is(Biomes.PLAINS),"Adjacent quart column is not overwritten");h.assertTrue(!t.transform(l,target,Biomes.DESERT,a)&&source.available==16&&t.stored.amount(a)==4,"Already transformed biome costs nothing");h.assertTrue(l.getChunkAt(target).isUnsaved(),"Biome mutation marked persistent");}finally{VisNetHandler.unregister(source);}pass(h);}
 @GameTest(template="empty") public static void focusSwitchRetainsStoredEssentiaAndBottomOnlyTransport(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(3,3,3));l.setBlockAndUpdate(p,Content.TERRAFORMER.get().defaultBlockState());l.setBlockAndUpdate(p.above(),Terraformer.FOCI.get("plains").get().defaultBlockState());var t=(Terraformer.Tile)l.getBlockEntity(p);var plant=TCAspects.catalog().require("herba");var fire=TCAspects.catalog().require("ignis");h.assertTrue(t.suction(Direction.DOWN)==128&&t.connectable(Direction.DOWN)&&!t.connectable(Direction.NORTH),"Original downward-only connector and suction");h.assertTrue(t.addEssentia(plant,7,Direction.DOWN)==7&&t.addEssentia(plant,2,Direction.UP)==0&&t.addEssentia(fire,2,Direction.DOWN)==0,"Only selected aspect enters through bottom");l.setBlockAndUpdate(p.above(),Terraformer.FOCI.get("desert").get().defaultBlockState());h.assertTrue(t.suctionType(null).equals(fire)&&t.stored.amount(plant)==7,"Changing focus retains prior stored aspect");var loaded=new Terraformer.Tile(p,l.getBlockState(p));loaded.load(t.saveWithoutMetadata());h.assertTrue(loaded.stored.amount(plant)==7,"Stored amounts survive reload");l.removeBlock(p.above(),false);h.assertTrue(t.suction(null)==0&&t.suctionType(null)==null,"Removing focus disables suction");pass(h);}
 @GameTest(template="empty") public static void everyFocusRetainsOriginalBiomeAspectAndAcquisition(GameTestHelper h){for(var entry:Terraformer.DEFINITIONS.entrySet()){var f=(Terraformer.Focus)Terraformer.FOCI.get(entry.getKey()).get();h.assertTrue(f.requiredAspect(h.getLevel(),BlockPos.ZERO).tag().equals(entry.getValue().aspect()),"Original focus aspect "+entry.getKey());h.assertTrue(h.getLevel().registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.BIOME).getHolder(f.createdBiome(h.getLevel(),BlockPos.ZERO)).isPresent(),"Target biome registered");h.assertTrue(!f.displayedBlock(h.getLevel(),BlockPos.ZERO).isEmpty(),"Original orbiting block exists");h.assertTrue(h.getLevel().getRecipeManager().byKey(new ResourceLocation("witchinggadgets","terraform_focus_"+entry.getKey())).isPresent(),"Focus has original acquisition recipe");}pass(h);}
 @GameTest(template="empty") public static void terraformerVentEventPassesServerBroadcastGate(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(3,3,3));l.setBlockAndUpdate(p,Content.TERRAFORMER.get().defaultBlockState());var state=l.getBlockState(p);h.assertTrue(state.triggerEvent(l,p,1,0x00ff00),"Server block-event dispatch must accept the vent event so vanilla broadcasts it to clients");h.assertTrue(!state.triggerEvent(l,p,99,0),"Unknown block events remain unhandled");pass(h);}
 static class Source implements VisEndpoint {final net.minecraft.server.level.ServerLevel world;final Key key;int available=20;Source(net.minecraft.server.level.ServerLevel l,BlockPos p){world=l;key=new Key(p,new ResourceLocation("witchinggadgets","terraform_test"));}public net.minecraft.world.level.Level level(){return world;}public Key key(){return key;}public boolean valid(){return true;}public int range(){return 8;}public boolean source(){return true;}public int drain(Aspect a,int n){if(!a.tag().equals("terra"))return 0;int used=Math.min(n,available);available-=used;return used;}}
 private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WITCHINGGADGETS_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
}
